		/** 
		 * Tests creating a new InvestmentPortfolio.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a InvestmentPortfolio");

			StringBuilder msg = new StringBuilder( "-- Failed to create a InvestmentPortfolio" );

			try {            
				InvestmentPortfolio entity = InvestmentPortfolioService.getInvestmentPortfolioInstance().createInvestmentPortfolio( generateNewEntity() );
				thePrimaryKey = entity.getInvestmentPortfolioId();
				LOGGER.info( "-- Successfully created a InvestmentPortfolio with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a InvestmentPortfolio. 
		 */
		public InvestmentPortfolio testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created InvestmentPortfolio" );

			InvestmentPortfolio entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read InvestmentPortfolio with primary key" );
			msg.append( thePrimaryKey );
			
			InvestmentPortfolioFetchOneSummary fetchOneSummary = new InvestmentPortfolioFetchOneSummary( thePrimaryKey );

			try {
				entity = InvestmentPortfolioService.getInvestmentPortfolioInstance().getInvestmentPortfolio( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found InvestmentPortfolio " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a InvestmentPortfolio.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a InvestmentPortfolio." );

			StringBuilder msg = new StringBuilder( "Failed to update a InvestmentPortfolio : " );        
			InvestmentPortfolio entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created InvestmentPortfolio." );

				// for use later on...
				thePrimaryKey = entity.getInvestmentPortfolioId();

				InvestmentPortfolioService proxy = InvestmentPortfolioService.getInvestmentPortfolioInstance();            
				proxy.updateInvestmentPortfolio( entity );   

				LOGGER.info( "-- Successfully saved InvestmentPortfolio - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a InvestmentPortfolio.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created InvestmentPortfolio." );

			try{
			    InvestmentPortfolio entity = testRead(); 
				InvestmentPortfolioService.getInvestmentPortfolioInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted InvestmentPortfolio with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete InvestmentPortfolio with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all InvestmentPortfolios.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of InvestmentPortfolios:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all InvestmentPortfolio : " );        
			List<InvestmentPortfolio> collection  = null;

			try {
				// call the static get method on the InvestmentPortfolioService
				collection = InvestmentPortfolioService.getInvestmentPortfolioInstance().getAllInvestmentPortfolio();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					InvestmentPortfolio entity = null;            
					Iterator<InvestmentPortfolio> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getInvestmentPortfolioId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

